import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { api } from '../api';

const AdminPage = () => {
    const [users, setUsers] = useState([]);
    const [error, setError] = useState(null);
    const navigate = useNavigate();

    useEffect(() => {
        // Пробуем получить пользователей. Если сервер ответит 403 Forbidden (не админ) - выкинет ошибку
        api.getUsers()
            .then(data => setUsers(data))
            .catch(err => setError("Доступ запрещен. Вы не администратор!"));
    }, []);

    const handleDelete = async (id) => {
        if (window.confirm("Точно удалить пользователя?")) {
            try {
                await api.deleteUser(id);
                setUsers(users.filter(u => u.id !== id));
            } catch (err) {
                alert("Ошибка при удалении");
            }
        }
    };

    if (error) return <div style={{ textAlign: 'center', marginTop: '50px', color: 'red' }}><h2>{error}</h2><button onClick={() => navigate('/')}>На главную</button></div>;

    return (
        <div className="container" style={{ marginTop: '50px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <h2>Панель Администратора (Пользователи)</h2>
                <button className="btn-add" onClick={() => navigate('/')}>Вернуться в магазин</button>
            </div>
            
            <table style={{ width: '100%', marginTop: '20px', borderCollapse: 'collapse' }}>
                <thead>
                    <tr style={{ background: '#fce7f3', textAlign: 'left' }}>
                        <th style={{ padding: '10px' }}>ID</th>
                        <th style={{ padding: '10px' }}>Email</th>
                        <th style={{ padding: '10px' }}>Роль</th>
                        <th style={{ padding: '10px' }}>Действия</th>
                    </tr>
                </thead>
                <tbody>
                    {users.map(u => (
                        <tr key={u.id} style={{ borderBottom: '1px solid #eee' }}>
                            <td style={{ padding: '10px' }}>{u.id}</td>
                            <td style={{ padding: '10px' }}>{u.email}</td>
                            <td style={{ padding: '10px' }}><b>{u.role}</b></td>
                            <td style={{ padding: '10px' }}>
                                <button onClick={() => handleDelete(u.id)} style={{ background: '#ef4444', color: 'white', border: 'none', padding: '5px 10px', borderRadius: '5px', cursor: 'pointer' }}>Удалить</button>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
};

export default AdminPage;
